/**
 * Seed real MNFSR district production data into MongoDB
 * Reads from district_production_real.json (generated by extract_mnfsr.py)
 *
 * Run from project root:
 *   node Backend/seeds/seed-real-district-data.js
 */

import mongoose from "mongoose";
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import dotenv from "dotenv";

import ProductionData from "../models/productionData.model.js";
import SurplusDeficit from "../models/surplusDeficit.model.js";
import Province       from "../models/province.model.js";   // must be imported before District.populate()
import District       from "../models/district.model.js";
import CropType       from "../models/cropType.model.js";


const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Load .env from project root (D:\Coding\FYP\CropConnect\.env)
dotenv.config({ path: path.resolve(__dirname, "..", "..", ".env") });
dotenv.config({ path: path.resolve(__dirname, "..", ".env") }); // fallback: Backend/.env


// Path to the JSON generated by extract_mnfsr.py (in project root)
const JSON_PATH = path.resolve(__dirname, "..", "..", "district_production_real.json");

const CONSUMPTION_RATES = {
  WHEAT:  124,  // kg/person/year
  RICE:    24,
  COTTON:   5,
};

async function seedRealDistrictData() {
  const raw = JSON.parse(fs.readFileSync(JSON_PATH, "utf-8"));
  const year = raw.year;                         // "2024-25"
  const districtData = raw.districts;            // keyed by district code
  const districtCodes = Object.keys(districtData);

  if (districtCodes.length === 0) {
    console.error("❌ No district data found in JSON. Run extract_mnfsr.py first.");
    process.exit(1);
  }

  console.log(`\n🌾 Seeding REAL MNFSR district data — year: ${year}`);
  console.log(`   Districts in JSON: ${districtCodes.length}`);

  // Load DB lookups
  const cropTypes = await CropType.find({});
  const cropMap = {};
  cropTypes.forEach(c => cropMap[c.code] = c);

  const dbDistricts = await District.find({}).populate("province");
  const districtMap = {};
  dbDistricts.forEach(d => districtMap[d.code] = d);

  let inserted = 0, skipped = 0, noData = 0;

  for (const [dCode, dInfo] of Object.entries(districtData)) {
    const dbDistrict = districtMap[dCode];
    if (!dbDistrict) {
      console.log(`   ⚠️  District '${dCode}' (${dInfo.district_name}) not in MongoDB — skipping`);
      skipped++;
      continue;
    }

    const crops = dInfo.crops || {};
    for (const [cropCode, cropData] of Object.entries(crops)) {
      const cropType = cropMap[cropCode];
      if (!cropType) continue;

      const production_t = cropData.production_t ?? 0;
      const area_ha      = cropData.area_ha      ?? 0;
      const yield_tph    = cropData.yield_t_per_ha ?? 0;

      if (production_t === 0 && area_ha === 0) {
        noData++;
        continue;  // district doesn't grow this crop
      }

      // ── Upsert ProductionData ─────────────────────────────────────────────
      await ProductionData.findOneAndUpdate(
        { year, districtCode: dCode, cropCode },
        {
          year,
          cropYear: { startYear: parseInt(year), endYear: parseInt(year) + 1 },
          level:        "district",
          province:     dbDistrict.province._id,
          provinceCode: dbDistrict.provinceCode,
          district:     dbDistrict._id,
          districtCode: dCode,
          cropType:     cropType._id,
          cropCode:     cropType.code,   // use model's own code field
          cropName:     cropType.name,
          areaCultivated: { value: area_ha,   unit: "hectares" },
          production:     { value: production_t, unit: "tonnes" },
          yield:          { value: yield_tph,  unit: "tonnes_per_hectare" },
          dataSource:   "MNFSR",          // must match enum in productionData.model.js
          reliability:  "high",
          notes: `Source: MNFSR CAP${year}`,
        },
        { upsert: true, new: true, runValidators: true }
      );


      // ── Surplus/Deficit ───────────────────────────────────────────────────
      const population  = dbDistrict.population || 0;
      const consumption = (population * CONSUMPTION_RATES[cropCode]) / 1000;
      const balance     = production_t - consumption;
      const pct         = consumption > 0 ? (balance / consumption) * 100 : 0;
      const selfSuf     = consumption > 0 ? (production_t / consumption) * 100 : 0;

      const status =
        balance >  consumption * 0.05 ? "surplus" :
        balance < -consumption * 0.05 ? "deficit" : "balanced";

      let severity = "none";
      if (status === "deficit") {
        const abs = Math.abs(pct);
        severity = abs > 30 ? "critical" : abs > 15 ? "moderate" : "mild";
      }

      await SurplusDeficit.findOneAndUpdate(
        { year, districtCode: dCode, cropCode: cropType.code },
        {
          year,
          level:        "district",
          province:     dbDistrict.province._id,
          provinceCode: dbDistrict.provinceCode,
          district:     dbDistrict._id,
          districtCode: dCode,
          cropType:     cropType._id,
          cropCode:     cropType.code,   // use model's own code field
          production:   production_t,
          consumption:  Math.round(consumption),
          balance:      Math.round(balance),
          status,
          surplusDeficitPercentage: Math.round(pct * 100) / 100,
          selfSufficiencyRatio:     Math.round(selfSuf * 100) / 100,
          severity,
          requiresIntervention: ["critical", "moderate"].includes(severity),
          dataSource:  "MNFSR",
          calculatedAt: new Date(),
        },
        { upsert: true, new: true, runValidators: true }
      );


      inserted++;
    }
  }

  console.log(`\n✅ Done!`);
  console.log(`   Inserted/updated : ${inserted} records`);
  console.log(`   Skipped (not in DB): ${skipped} districts`);
  console.log(`   Skipped (zero data): ${noData} crop entries`);
}

// ── Connect & Run ─────────────────────────────────────────────────────────────
const MONGO_URI = process.env.MONGO_URI || process.env.MONGODB_URI || "mongodb://localhost:27017/cropconnect";

mongoose.connect(MONGO_URI)
  .then(async () => {
    console.log("✅ Connected to MongoDB");
    await seedRealDistrictData();
    await mongoose.disconnect();
    console.log("✅ Disconnected. Done.");
  })
  .catch(err => {
    console.error("❌ DB connection failed:", err.message);
    process.exit(1);
  });
